"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6508],{2572(e){e.exports=JSON.parse('{"title":"CSS\ub9cc\uc73c\ub85c \ub808\uc774\uc544\uc6c3 \uc798 \ub9cc\ub4e4\uae30","date":"2025-08-21","coverUrl":"/kudzu-based-bench/assets/notion/1dda5bc3384fff22.png","html":"<h1 data-notion-block-id=\\"24ee548d-8a8e-8058-9efc-fca8d975ac6a\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"250e548d-8a8e-804c-958f-d91de37eb72e\\" id=\\"250e548d-8a8e-804c-958f-d91de37eb72e\\">CSS\ub9cc\uc73c\ub85c \ub808\uc774\uc544\uc6c3 \uc798 \ub9cc\ub4e4\uae30</h2><a href=\\"https://ishadeed.com/article/time-layout/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/time-layout/</a><p data-notion-block-id=\\"250e548d-8a8e-80a1-aadc-cbb8498b59c1\\">time.com\uc758 \uba54\uc778\ud398\uc774\uc9c0\ub97c CSS Layout\uc744 \ud1b5\ud574\uc11c \uac1c\uc120\ud558\ub294 \uacfc\uc815\uc744 (\uba87 \uac00\uc9c0\uc758) \ucd5c\uc2e0 CSS\ub97c \ud1b5\ud574\uc11c(\ud2b9\ud788 \uac04\ub2e8\ud558\uac8c \uc9c0\ub098\ucce4\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/37250bc2-728f-4005-9bc5-c041e79d1790#100e548d-8a8e-802e-8f9c-dbdbc25886ed\\"><code>display: contents;</code></a>\ub97c \uc911\uc2ec\uc73c\ub85c) \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ucd5c\uc2e0 CSS\ub97c \ub9ce\uc774 \uc0ac\uc6a9\ud558\uace0 \uc788\uc9c0\ub9cc CSS Layout\ub9cc\uc73c\ub85c \ubc18\uc751\ud615 Layout\uc744 \uad6c\ucd95\ud558\ub294 \ubc29\uc2dd\uc740 CSS3(\ucd5c\uadfc\uc740 CSS5\ub77c\uace0 \ubd80\ub974\ub2c8)\ubc29\uc2dd\uc5d0\uc11c\ub3c4 \uc0ac\uc6a9\ud560\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"250e548d-8a8e-8050-9068-d6606fd3f354\\" id=\\"250e548d-8a8e-8050-9068-d6606fd3f354\\">\uc65c LLM\uc740 \uc544\uc9c1 \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ub9cc\ub4e4\uc9c0 \ubabb\ud560\uae4c</h2><a href=\\"https://zed.dev/blog/why-llms-cant-build-software\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zed.dev/blog/why-llms-cant-build-software</a><p data-notion-block-id=\\"250e548d-8a8e-800b-bcff-ccbe8f4df8af\\"><a href=\\"https://clickhouse.com/blog/llm-observability-challenge\\">LLM\uc774 SRE\ub97c \ub300\uccb4\ud560 \uc218 \uc788\uc744\uae4c?</a>\uc640 \ube44\uc2b7\ud55c \uad00\uc810\uc73c\ub85c\uc11c, LLM\uc758 \uba58\ud0c8\ubaa8\ub378\uc774 \uc720\uc9c0\ud560 \uc218 \uc5c6\uae30 \ub54c\ubb38\uc5d0 \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ub9cc\ub4e4\uc9c0 \ubabb\ud558\uace0, \ubcf4\uc870\ub3c4\uad6c\ub85c\ubc16\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \ubc16\uc5d0 \uc5c6\ub294 \ud765\ubbf8\ub85c\uc6b4 \uad00\uc810\uc758 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"251e548d-8a8e-80f4-a17f-f0048dd5c1a3\\" id=\\"251e548d-8a8e-80f4-a17f-f0048dd5c1a3\\">JSON.stringify\uac00 \ube68\ub77c\uc84c\ub2e4.</h2><a href=\\"https://v8.dev/blog/json-stringify\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v8.dev/blog/json-stringify</a><p data-notion-block-id=\\"250e548d-8a8e-8057-8576-ed6601a7e116\\">\uc5ec\ub7ec\uac00\uc9c0 \uc804\ub7b5\uacfc \uc54c\uace0\ub9ac\uc998, \ucd5c\uc801\ud654\ub85c <code>JSON.stringify</code>\uac00 \ube68\ub77c\uc84c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \ub0b4\uc6a9\uc740 \uc5b4\ub835\uae30\ub3c4 \ud558\uace0, \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uac1c\ubc1c\uc790\uac00 \uc54c \ud544\uc694 \uc5c6\uc744\uc9c0\ub3c4 \ubaa8\ub974\ub294 \ub0b4\uc6a9\ub4e4\uc774 \ub9ce\uc9c0\ub9cc, \ucd5c\uc801\ud654\uc2dc\uc5d0 \uac1d\uccb4\uc758 hidden class\ub97c \uc0ac\uc6a9\ud588\uace0, \uadf8\ub9ac\uace0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#b0fa8093-7010-49bd-9e12-b95e81fcacef\\">Monomorphism \uac1d\uccb4\uc77c \uacbd\uc6b0</a> \ucd5c\uc801\ud654\uac00 \ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uba85\uc2ec\ud574\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"250e548d-8a8e-80cc-80d8-d9c706e78841\\" id=\\"250e548d-8a8e-80cc-80d8-d9c706e78841\\">React key\ub294 \ub9ac\uc2a4\ud2b8\ub9cc\uc744 \uc704\ud55c\uac8c \uc544\ub2c8\ub2e4</h2><a href=\\"https://www.youtube.com/watch?v=l-2zAVxdSDM\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=l-2zAVxdSDM</a><p data-notion-block-id=\\"250e548d-8a8e-8081-829d-df33dffcee7a\\">React key\ub294 \ub9ac\uc2a4\ud2b8\ub9cc\uc744 \uc704\ud55c\uac8c \uc544\ub2c8\uba70, \uc7ac\ub80c\ub354\ub9c1\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4\ub294 \uac83\uc744 \uc54c\ub824\uc8fc\ub294 \uac04\ub2e8\ud55c \uc601\uc0c1\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/1f9e548d-8a8e-8014-9990-cc334dc08c4a#1fde548d-8a8e-80fa-9b3e-f078aca4ca32\\">Early return\uc740 \ub54c\ub85c \ub3c5\uc774 \ub41c\ub2e4</a>\uc5d0\ub3c4 \ub098\uc640\uc788\ub4ef\uc774, JSX\uad6c\uc870\ub97c \uc798 \uc124\uacc4\ud558\ub294 \uac83\ub3c4 \uc131\ub2a5\uc744 \ub192\uc774\ub294\ub370 \ub3c4\uc6c0\uc744 \uc90d\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"24ee548d-8a8e-8078-af2e-e6652d268fdc\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"250e548d-8a8e-807d-81c6-ec71eb60e577\\" id=\\"250e548d-8a8e-807d-81c6-ec71eb60e577\\">Tanstack/devtools \uad6c\uc870 \ubd84\uc11d\ud558\uae30</h2><a href=\\"https://www.youtube.com/watch?v=Em2MeE-GTK0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=Em2MeE-GTK0</a><p data-notion-block-id=\\"250e548d-8a8e-800e-ba85-c1a7937b8afc\\">\ubc94\uc6a9 \uac1c\ubc1c\ub3c4\uad6c\uc778 TanStack DevTools\uc740 Tanstack \uc0dd\ud0dc\uacc4\uc5d0 agnostic\ud558\uac8c \ub9cc\ub4e4\uc5b4\uc9c8 \uac1c\ubc1c\uc790 \ub3c4\uad6c\uc785\ub2c8\ub2e4. \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0, \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc9c8\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"250e548d-8a8e-80d5-913b-e228b580d27e\\" id=\\"250e548d-8a8e-80d5-913b-e228b580d27e\\">Cloudflare\ub294 \uc77c\ubc18\uc801\uc778 CDN\uacfc \ub2e4\ub974\ub2e4.</h2><a href=\\"https://magecdn.com/blog/2025/08/11/cloudflare-not-a-cdn/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://magecdn.com/blog/2025/08/11/cloudflare-not-a-cdn/</a><p data-notion-block-id=\\"24ee548d-8a8e-8048-82f5-eb034e0743b2\\">Cloudflare\uac00 \uc77c\ubc18\uc801\uc778 CDN\uacfc \ub2e4\ub978 \uc774\uc720\ub97c \uc9da\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"250e548d-8a8e-808b-9c22-de22caccf2fe\\" id=\\"250e548d-8a8e-808b-9c22-de22caccf2fe\\">\ub54c\ub85c\ub294 \uac04\ub2e8\ud55c \uac83\uc774 \uc131\ub2a5\uc744 \ud5a5\uc0c1\ud55c\ub2e4. </h2><a href=\\"https://medium.com/expedia-group-tech/12-tips-to-improve-client-side-page-performance-88c7bec27933\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/expedia-group-tech/12-tips-to-improve-client-side-page-performance-88c7bec27933</a><p data-notion-block-id=\\"250e548d-8a8e-800f-9baf-d6f6ff3dac4c\\">DOM\uc744 \uc904\uc774\uac70\ub098, \uc61b\ub0a0 \ucf54\ub4dc\ub97c \uc5c6\uc560\ub294 \ub4f1, \ud074\ub77c\uc774\uc5b8\ud2b8 \uc131\ub2a5 \ud5a5\uc0c1\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \ud301\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"250e548d-8a8e-803b-bfa8-e67d01368232\\" id=\\"250e548d-8a8e-803b-bfa8-e67d01368232\\">\uac04\ub2e8\ud558\uc9c0\ub9cc \uc5b4\ub824\uc6b4, \uc88b\uc740 \ubb38\uc11c \uc791\uc131\ubc95</h2><a href=\\"https://grantslatton.com/how-to-design-document\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://grantslatton.com/how-to-design-document</a><h2 data-notion-block-id=\\"24fe548d-8a8e-80e5-bcd5-f1dc0fcf7f0d\\" id=\\"24fe548d-8a8e-80e5-bcd5-f1dc0fcf7f0d\\">Local-First\uc758 \ud604\uc7ac, \uadf8\ub9ac\uace0 \ubbf8\ub798</h2><a href=\\"https://www.youtube.com/watch?v=NMq0vncHJvU\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=NMq0vncHJvU</a><p data-notion-block-id=\\"253e548d-8a8e-805b-8bb4-e96f4733c2c7\\">local-first \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc758 \uacfc\uac70, \ud604\uc7ac, \uadf8\ub9ac\uace0 \ubbf8\ub798\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. CRDT\uc640 P2P \ubc29\uc2dd\uc744 \ub118\uc5b4\uc11c, \uc11c\ube44\uc2a4 \uc885\ub8cc \ud6c4\uc5d0\ub3c4 \uc0ac\uc6a9 \uac00\ub2a5\ud55c, \uadf8\ub9ac\uace0 \ud504\ub85c\ud1a0\ucf5c \ud638\ud658\uae4c\uc9c0 \ubc14\ub77c\ubcf4\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"24ee548d-8a8e-804e-a377-ca3b23d633b5\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://www.zachleat.com/web/adventures-in-date-parsing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.zachleat.com/web/adventures-in-date-parsing/</a><p data-notion-block-id=\\"250e548d-8a8e-802e-a2ad-db14c1ae1d3a\\">\uacb0\uad6d \ub370\uc774\ud130 \ud30c\uc2f1 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uae00\uc774\uc9c0\ub9cc, \ub0a0\uc9dc \ud45c\ud604 \uad6c\uc131\uc5d0 \ub530\ub77c\uc11c \ud30c\uc2f1\uc774 \ub418\ub294\uc9c0, \uc548\ub418\ub294\uc9c0\ub97c \ud45c\uc2dc\ud574 \ub454 \uac83\uc740 \ub9e4\uc6b0 \uc88b\uc740 \uc9c0\uce68\uc774 \ub420 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \ub370\uc774\ud130 \ud30c\uc2f1\uc5d0\ub9cc \uc0ac\uc6a9\ud55c\ub2e4\uba74 \uc544\uc8fc \uc88b\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \ub420 \uc218 \uc788\uaca0\ub124\uc694.</p><a href=\\"https://github.com/chakra-ui/panda/discussions/3321\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/chakra-ui/panda/discussions/3321</a><p data-notion-block-id=\\"250e548d-8a8e-80ae-b985-cf20f8334d02\\">Panda CSS\uac00 \uba54\uc774\uc800 \ubc84\uc804 \ucd9c\uc2dc\uac00 \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"250e548d-8a8e-8053-8756-ebbc4970e0b1\\"></p>"}')}}]);